package com.metaverse.coin.strategy.core.arbitrage.multi;
import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.*; import java.util.List; import static org.junit.jupiter.api.Assertions.*;
class CrossExchangeOpportunityStabilityGateTest {
 @Test void approvesOnlyAfterWindow(){Instant now=Instant.now();var gate=new CrossExchangeOpportunityStabilityGate(Duration.ofMinutes(3));var o=opportunity(now);assertFalse(gate.stable(o,now));assertFalse(gate.stable(o,now.plusSeconds(179)));assertTrue(gate.stable(o,now.plusSeconds(180)));}
 @Test void missingObservationResetsTheStabilityWindow(){Instant now=Instant.now();var gate=new CrossExchangeOpportunityStabilityGate(Duration.ofMinutes(3));var o=opportunity(now);assertFalse(gate.stable(o,now));gate.completeScan("BTCUSDT",List.of());assertFalse(gate.stable(o,now.plusSeconds(180)));assertTrue(gate.stable(o,now.plusSeconds(360)));}
 @Test void directionalFlipResetsThePreviousPairWindow(){Instant now=Instant.now();var gate=new CrossExchangeOpportunityStabilityGate(Duration.ofMinutes(3));var original=opportunity(now);var flipped=opportunity(now,Exchange.OKX,Exchange.BINANCE);assertFalse(gate.stable(original,now));assertFalse(gate.stable(flipped,now.plusSeconds(60)));gate.completeScan("BTCUSDT",List.of(flipped));assertFalse(gate.stable(original,now.plusSeconds(180)));}
 private CrossExchangeOpportunity opportunity(Instant n){var l=new NormalizedFundingRateSnapshot(Exchange.BINANCE,"BTCUSDT",new BigDecimal("-0.001"),8,n.plusSeconds(3600),BigDecimal.TEN,BigDecimal.TEN,n);var s=new NormalizedFundingRateSnapshot(Exchange.OKX,"BTCUSDT",new BigDecimal("-0.0001"),8,n.plusSeconds(3600),BigDecimal.TEN,BigDecimal.TEN,n);return new CrossExchangeOpportunity("x","BTCUSDT",l,s,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.TEN,CrossExchangeOpportunity.Status.QUALIFIED,null,n);}
 private CrossExchangeOpportunity opportunity(Instant n,Exchange longExchange,Exchange shortExchange){var l=new NormalizedFundingRateSnapshot(longExchange,"BTCUSDT",new BigDecimal("-0.001"),8,n.plusSeconds(3600),BigDecimal.TEN,BigDecimal.TEN,n);var s=new NormalizedFundingRateSnapshot(shortExchange,"BTCUSDT",new BigDecimal("-0.0001"),8,n.plusSeconds(3600),BigDecimal.TEN,BigDecimal.TEN,n);return new CrossExchangeOpportunity("x","BTCUSDT",l,s,BigDecimal.ONE,BigDecimal.ONE,BigDecimal.TEN,CrossExchangeOpportunity.Status.QUALIFIED,null,n);}
}
